}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The sheet's rates for each grade, each from a date (or from the beginning of time): set one grade
 * and from-date at a time, replacing any rate it had. A date's rate is the one with the latest
 * from-date on or before it; a grade with none in force on a date takes the sheet's ancestors' ({@link InheritedRates}).
 */
@Service
public class RateService {

    private final RateRepository rates;
    private final RateLogRepository log;
    private final SheetRepository sheets;
    private final RollupService rollup;
    private final InheritedRates inherited;
    private final Audit audit;

    public RateService(RateRepository rates, RateLogRepository log, SheetRepository sheets, RollupService rollup,
            InheritedRates inherited, Audit audit) {
        this.rates = rates;
        this.log = log;
        this.sheets = sheets;
        this.rollup = rollup;
        this.inherited = inherited;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
    }

    /**
     * The grade's rate on the date: the one with the latest from-date on or before it, if any and not ended;
     * else the nearest ancestor's in force then.
     */
    @Transactional(readOnly = true)
    public Optional<Rate> on(String sheetId, String grade, LocalDate date) {
        return inherited.of(sheetId).inForce(grade, date);
    }

    /** The sheet's rates and its ancestors' ({@link InheritedRates}), as they are now. */
    @Transactional(readOnly = true)
    public RateLevels levels(String sheetId) {
        return inherited.of(sheetId);
    }

    /** The rates of the sheet's ancestors, nearest first, each by grade: as they are now, or as they stood at the end of the date given. */
    @Transactional(readOnly = true)
    public List<Map<String, List<Rate>>> ancestors(String sheetId, LocalDate asOf) {
        return asOf == null ? inherited.ancestors(sheetId) : inherited.ancestorsAsOf(sheetId, asOf);
    }

    /**
     * The sheet's rates by grade as they stood at the end of the date: of those set while the sheet's
     * today was on or before it, the last set for each grade and from-date.
     */
    @Transactional(readOnly = true)
    public Map<String, List<Rate>> asOf(String sheetId, LocalDate date) {
        return inherited.asOf(sheetId, date);
    }

    /** The sheet\'s rates and its ancestors\', each as they stood at the end of the date. */
    @Transactional(readOnly = true)
    public RateLevels levelsAsOf(String sheetId, LocalDate date) {
        return inherited.levelsAsOf(sheetId, date);
    }

    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        if (to != null && from != null && to.isBefore(from)) throw new RateDatesException();
        // Lock the sheet so two users setting the same grade and from-date at once replace one rate.
        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Optional<Rate> existing = from == null
                ? rates.findBySheetIdAndGradeAndFromDateIsNull(sheetId, grade)
                : rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from);
        Rate rate = existing.orElseGet(() -> new Rate(sheetId, grade, from, to, pct));
        rate.setPct(pct);
        rate.setToDate(to);
        Rate saved = rates.saveAndFlush(rate);
        log.saveAndFlush(new RateLog(saved, today));
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user.strip()
                + " grade=" + saved.getGrade() + " rate=" + saved.getPct().setScale(2).toPlainString()
                + (saved.getFromDate() != null ? " from=" + saved.getFromDate() : "")
                + (saved.getToDate() != null ? " to=" + saved.getToDate() : ""));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Imported rates: lines of grade,rate,from,to (the last two may be absent or blank), each checked
 * first with the rate form's rules, then set in order exactly as the form sets one (replacing a rate
 * for the same grade and from-date). Blank lines are skipped; a paste with no line is refused. It is
 * one change: a line that is refused refuses them all.
 */
@Service
public class RateImportService {

    private static final Pattern GRADE = Pattern.compile("[ABC]");
    private static final Pattern PCT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?");
    private static final Pattern DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");

    private record Line(String grade, BigDecimal pct, LocalDate from, LocalDate to) {}

    private final RateService rates;

    public RateImportService(RateService rates) {
        this.rates = rates;
    }

    /** The rates set, in the order of their lines. */
    @Transactional
    public List<Rate> importRates(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        for (String raw : text.split("\\R")) {
            if (raw.isBlank()) continue;
            lines.add(parse(raw));
        }
        if (lines.isEmpty()) throw new RateImportRefusedException();
        List<Rate> set = new ArrayList<>();
        for (Line line : lines) {
            set.add(rates.set(sheetId, user, line.grade(), line.from(), line.to(), line.pct()));
        }
        return set;
    }

    private Line parse(String raw) {
        String[] fields = raw.split(",", -1);
        if (fields.length < 2 || fields.length > 4) throw new RateImportRefusedException();
        String grade = fields[0].strip();
        String pct = fields[1].strip();
        LocalDate from = date(fields.length > 2 ? fields[2].strip() : "");
        LocalDate to = date(fields.length > 3 ? fields[3].strip() : "");
        if (!GRADE.matcher(grade).matches() || !PCT.matcher(pct).matches()) throw new RateImportRefusedException();
        if (from != null && to != null && to.isBefore(from)) throw new RateImportRefusedException();
        return new Line(grade, new BigDecimal(pct).setScale(2), from, to);
    }

    /** A yyyy-mm-dd date, or null when blank. */
    private static LocalDate date(String text) {
        if (text.isEmpty()) return null;
        if (!DATE.matcher(text).matches()) throw new RateImportRefusedException();
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new RateImportRefusedException();
        }
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A line of a sheet's rate log: a rate set for a grade and from-date, as it was set, on the sheet's
 * today then (null: before this was kept). A later line for the same grade and from-date replaced it.
 */
@Entity
@Table(name = "rate_log")
public class RateLog {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    @Column(name = "pct", nullable = false, precision = 7, scale = 2)
    private BigDecimal pct;

    @Column(name = "set_on")
    private LocalDate setOn;

    protected RateLog() {}

    public RateLog(Rate rate, LocalDate setOn) {
        this.sheetId = rate.getSheetId();
        this.grade = rate.getGrade();
        this.fromDate = rate.getFromDate();
        this.toDate = rate.getToDate();
        this.pct = rate.getPct();
        this.setOn = setOn;
    }

    public String getGrade() { return grade; }

    public LocalDate getFromDate() { return fromDate; }

    /** Whether it was set on or before the date. */
    public boolean setBy(LocalDate date) { return setOn == null || !setOn.isAfter(date); }

    /** The rate as this line set it. */
    public Rate toRate() { return new Rate(sheetId, grade, fromDate, toDate, pct); }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * A sheet's rates by grade, then those of each of its ancestors, nearest first (see
 * {@link net.officefloor.hq.app.sheet.SheetParent}): a grade's rate on a date is the sheet's own in
 * force then, else the nearest ancestor's in force then.
 */
public record RateLevels(List<Map<String, List<Rate>>> levels) {

    /** The grade's rate on the date: the first level's that has one in force then. */
    public Optional<Rate> inForce(String grade, LocalDate date) {
        for (Map<String, List<Rate>> level : levels) {
            Optional<Rate> rate = Rate.inForce(level.getOrDefault(grade, List.of()), date);
            if (rate.isPresent()) return rate;
        }
        return Optional.empty();
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.sheet.SheetParent;
import net.officefloor.hq.app.sheet.SheetParentRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The rates a sheet's figures use: its own, then, for a grade and date it has none in force on, its
 * parent's, its parent's parent's, up to {@link SheetParent#LEVELS} levels up.
 */
@Service
public class InheritedRates {

    private final RateRepository rates;
    private final RateLogRepository log;
